1// Return the maximum element of he list.
2T find_max(){
3    Node<T>* current = head;
4    // Initally we assume
5    // the head has a maximum value
6    int maximum = head->data;
7    
8    // Loop until the next node is a head
9    while(current->next != head){
10        current = current->next;
11        // Compare if the value of current node
12        // is greater than the maximum value
13        if(current->data > maximum){
14            // update the maximum value
15           maximum = current->data;
16        }
17    }
18    return maximum;
19}
